function show(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000)}
async function request(path,{method='GET',body,token}={}){const response=await fetch(SUPABASE_URL+path,{method,headers:{apikey:API_KEY,'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error_description||data.msg||data.error||'Noe gikk galt. Prøv igjen.');return data}
function saveSession(value){session=value;value?localStorage.setItem(SESSION_KEY,JSON.stringify(value)):localStorage.removeItem(SESSION_KEY)}
async function refreshSession(){if(!session?.refresh_token)return false;try{const data=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token}});saveSession(data);return true}catch{saveSession(null);return false}}
async function authenticated(path,options={}){if(!session?.access_token)throw new Error('Du må logge inn.');try{return await request(path,{...options,token:session.access_token})}catch(error){if(/jwt|token|expired/i.test(error.message)&&await refreshSession())return request(path,{...options,token:session.access_token});throw error}}
function initials(name){return name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function roleText(role){return({employee:'Ansatt',manager:'Avdelingsleder',admin:'Admin'})[role]||role}

