async function loadClock(){try{clockState=await authenticated('/functions/v1/time-clock');if(!$('#periodMonth').value)$('#periodMonth').value=localMonth();renderClock();renderQrStatus()}catch(error){show(error.message);$('#clockStatus').textContent='Kunne ikke hente status'}}
function renderQrStatus(){if(!$('#qrStatusText'))return;const qr=clockState?.qr_status;if(!qr){$('#qrStatusText').textContent='Ingen aktiv QR-kode';$('#qrStatusDetail').textContent='Lag en ny kode før de ansatte kan stemple med QR.';$('#revokeQr').classList.add('hidden');return}$('#qrStatusText').textContent='Aktiv QR-kode';const mode=qr.location_check_required?'100-meterskontroll er aktiv.':'Testversjon: posisjonsgrensen er deaktivert.';$('#qrStatusDetail').textContent=`${mode} Gyldig til ${new Date(qr.expires_at).toLocaleDateString('nb-NO')}.`;$('#revokeQr').classList.remove('hidden')}
function formatTime(value){return new Date(value).toLocaleTimeString('nb-NO',{timeZone:'Europe/Oslo',hour:'2-digit',minute:'2-digit'})}
function formatDay(value){return new Date(value).toLocaleDateString('nb-NO',{timeZone:'Europe/Oslo',weekday:'long',day:'2-digit',month:'2-digit'})}
function durationHours(entry){return entry.ended_at?Math.max(0,(new Date(entry.ended_at)-new Date(entry.started_at))/3600000):0}
function localMonth(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit'}).format(new Date()).slice(0,7)}
function osloMonth(value){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit'}).format(new Date(value)).slice(0,7)}
function hours(value){return Number(value||0).toLocaleString('nb-NO',{minimumFractionDigits:0,maximumFractionDigits:2})+' t'}
function renderClock(){const open=clockState?.open_entry;$('#clockStatus').textContent=open?'Du er stemplet inn':'Du er ikke stemplet inn';$('#clockDetail').textContent=open?`Siden ${formatTime(open.started_at)} · ${clockState.worksite.name}`:`${clockState.worksite.address} · ${clockState.worksite.radius_meters} meter`;$('#clockDot').classList.toggle('active',Boolean(open));$('#scanClock').textContent=open?'Skann QR-kode og stemple ut':'Skann QR-kode og stemple inn';const month=$('#periodMonth').value||localMonth(),entries=(clockState.entries||[]).filter(e=>osloMonth(e.started_at)===month),adjustments=(clockState.adjustments||[]).filter(a=>String(a.work_date).slice(0,7)===month),sick=adjustments.filter(a=>a.category==='sick_pay'),approval=(clockState.approvals||[]).find(a=>String(a.month_start).slice(0,7)===month);$('#monthTotal').textContent=hours(entries.reduce((sum,e)=>sum+durationHours(e),0)+sick.reduce((sum,a)=>sum+Number(a.hours),0));$('#overtime40').textContent=hours(adjustments.filter(a=>a.category==='overtime_40').reduce((sum,a)=>sum+Number(a.hours),0));$('#overtime100').textContent=hours(adjustments.filter(a=>a.category==='overtime_100').reduce((sum,a)=>sum+Number(a.hours),0));$('#monthState').textContent=approval?.status==='locked'?'Låst måned':approval?.status==='approved'?'Godkjent måned':'Åpen måned';$('#monthState').className=`month-state ${approval?.status||'open'}`;const rows=[...entries.map(e=>({date:String(e.started_at),html:`<div class="time-row"><span><strong>${formatDay(e.started_at)}</strong><small>${e.kind==='sick_pay'?'Sykepenger · ':''}${formatTime(e.started_at)}–${e.ended_at?formatTime(e.ended_at):'Pågår'}${e.auto_clocked_out?' · Automatisk utstemplet':''}</small></span><strong>${e.ended_at?hours(durationHours(e)):'Aktiv'}</strong></div>`})),...sick.map(a=>({date:`${a.work_date}T12:00:00Z`,html:`<div class="time-row"><span><strong>${displayDate(a.work_date)}</strong><small>Sykefravær · godkjent</small></span><strong>${hours(a.hours)}</strong></div>`}))].sort((a,b)=>b.date.localeCompare(a.date));$('#timeRows').innerHTML=rows.length?rows.map(r=>r.html).join(''):'<p class="muted">Ingen registreringer i denne måneden.</p>'}
$('#periodMonth').onchange=renderClock;

function stopScanner(){if(scannerTimer)cancelAnimationFrame(scannerTimer);scannerTimer=null;scannerStream?.getTracks().forEach(track=>track.stop());scannerStream=null;$('#scannerVideo').srcObject=null;if($('#scannerDialog').open)$('#scannerDialog').close()}
async function startScanner(){const dialog=$('#scannerDialog');dialog.showModal();$('#manualQr').classList.add('hidden');$('#scannerVideo').classList.remove('hidden');if(!('BarcodeDetector'in window)){showManualScanner('Kamera-skanning støttes ikke i denne nettleseren.');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=$('#scannerVideo');video.srcObject=scannerStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});const detect=async()=>{if(!scannerStream)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){stopScanner();await clockWithQr(codes[0].rawValue);return}}catch{}scannerTimer=requestAnimationFrame(detect)};detect()}catch{showManualScanner('Kameraet kunne ikke åpnes. Du kan skrive inn innholdet fra QR-koden.') }}
function showManualScanner(message){$('#scannerHelp').textContent=message;$('#scannerVideo').classList.add('hidden');$('#manualQr').classList.remove('hidden')}
function getPosition(){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,()=>reject(new Error('Posisjonen kunne ikke hentes. Tillat posisjonstilgang og prøv igjen.')),{enableHighAccuracy:true,timeout:15000,maximumAge:0}))}
async function clockWithQr(qrToken){const button=$('#scanClock');button.disabled=true;button.textContent='Kontrollerer posisjon …';try{const position=await getPosition();const action=clockState?.open_entry?'clock_out':'clock_in';const data=await authenticated('/functions/v1/time-clock',{method:'POST',body:{action,qr_token:qrToken,latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy}});show(action==='clock_in'?`Stemplet inn ${formatTime(data.entry.started_at)}.`:`Stemplet ut ${formatTime(data.entry.ended_at)}.`);await loadClock()}catch(error){show(error.message)}finally{button.disabled=false;renderClock()}}
