$('#issueQr').onclick=async()=>{if(!confirm('Lage en ny QR-kode? Den forrige koden blir ugyldig med én gang.'))return;const button=$('#issueQr');button.disabled=true;button.textContent='Lager …';try{const baseUrl=`${location.origin}${location.pathname}`;const data=await authenticated('/functions/v1/time-clock',{method:'POST',body:{action:'issue_qr',base_url:baseUrl}});const bytes=new TextEncoder().encode(data.qr_svg);let binary='';bytes.forEach(byte=>binary+=String.fromCharCode(byte));const url=`data:image/svg+xml;base64,${btoa(binary)}`;$('#qrImage').src=url;$('#downloadQr').href=url;$('#qrWorksite').textContent=data.worksite;const mode=data.location_check_required?'Posisjonskontroll er aktiv.':'Testkode: posisjonsgrensen er deaktivert.';$('#qrExpiry').textContent=`${mode} Gyldig til ${new Date(data.expires_at).toLocaleDateString('nb-NO')}. Last ned koden nå; den kan ikke hentes frem igjen.`;$('#qrResult').classList.remove('hidden');show(data.location_check_required?'Ny QR-kode er laget.':'Ny testkode er laget uten posisjonsgrense.')}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Lag ny QR-kode'}};
$('#revokeQr').onclick=async()=>{if(!confirm('Sperre gjeldende QR-kode? Ansatte kan ikke stemple med den etterpå.'))return;const button=$('#revokeQr');button.disabled=true;try{await authenticated('/functions/v1/time-clock',{method:'POST',body:{action:'revoke_qr'}});$('#qrResult').classList.add('hidden');show('QR-koden er sperret.');await loadClock()}catch(error){show(error.message)}finally{button.disabled=false}};
async function loadEmployees(){const data=await authenticated('/functions/v1/employee-admin');employees=data.employees||[];renderEmployees();const select=$('#summaryEmployee'),selected=select.value;select.innerHTML='<option value="">Alle ansatte samlet</option>'+employees.map(x=>`<option value="${x.id}">${escapeHtml(x.employee_number)} · ${escapeHtml(x.full_name)}</option>`).join('');select.value=employees.some(x=>x.id===selected)?selected:'';const approval=$('#approvalEmployee'),approvalSelected=approval.value;approval.innerHTML='<option value="">Velg ansatt</option>'+employees.map(x=>`<option value="${x.id}">${escapeHtml(x.employee_number)} · ${escapeHtml(x.full_name)}</option>`).join('');approval.value=employees.some(x=>x.id===approvalSelected)?approvalSelected:''}
function employeeWorkStatus(x){if(x.open_entry)return `<div class="work-status clocked-in"><strong>Stemplet inn · kl. ${formatTime(x.open_entry.started_at)}</strong><small>${x.open_entry.source==='manual'?'Manuelt registrert':'På jobb nå'}</small></div>`;if(x.last_entry?.ended_at)return `<div class="work-status"><strong>${x.last_entry.auto_clocked_out?'Automatisk utstemplet':'Ikke stemplet inn'}</strong><small>Sist ut · kl. ${formatTime(x.last_entry.ended_at)}</small></div>`;return '<div class="work-status"><strong>Ikke stemplet inn</strong><small>Ingen registrering</small></div>'}
function renderEmployees(){const term=$('#search').value.trim().toLowerCase();const items=employees.filter(x=>[x.employee_number,x.full_name,x.email,x.phone_number].join(' ').toLowerCase().includes(term));$('#empty').classList.toggle('hidden',items.length>0);$('#rows').innerHTML=items.map(x=>`<tr class="${x.active?'':'inactive'}"><td><div class="person"><span class="avatar">${initials(x.full_name)}</span><strong>${escapeHtml(x.full_name)}</strong></div></td><td>${escapeHtml(x.employee_number)}</td><td>${escapeHtml(x.email)}<br><small>${escapeHtml(x.phone_number||'Ingen telefon')}</small></td><td>${roleText(x.role)}</td><td>${employeeWorkStatus(x)}</td><td><span class="status ${x.active?'active':''}">${x.active?'Aktiv':'Inaktiv'}</span></td><td><div class="actions">${x.active?`<button class="secondary" data-clock="${x.id}">${x.open_entry?'Stemple ut':'Stemple inn'}</button>`:''}<button class="small" data-edit="${x.id}">Rediger</button><button class="${x.active?'danger':'secondary'}" data-toggle="${x.id}">${x.active?'Sett inaktiv':'Aktiver'}</button></div></td></tr>`).join('')}
