function hmsDocumentRows(adminView=false){const docs=hmsData.documents||[];return docs.length?docs.map(d=>`<div class="hms-row ${d.active?'':'inactive'}"><div><strong>${escapeHtml(d.title)}</strong><small>${escapeHtml(d.original_name)} · ${(d.size_bytes/1048576).toLocaleString('nb-NO',{maximumFractionDigits:1})} MB</small></div><div class="actions"><a class="small hms-link" href="${d.url}" target="_blank" rel="noopener">Åpne</a>${adminView?`<button class="secondary" data-hms-doc="${d.id}" data-active="${d.active}">${d.active?'Deaktiver':'Aktiver'}</button>`:''}</div></div>`).join(''):'<p class="muted">Ingen HMS-dokumenter er lagt inn.</p>'}
function renderHms(){if(currentEmployee?.role==='admin'){$('#adminHmsDocuments').innerHTML=hmsDocumentRows(true);$('#adminHmsDeviations').innerHTML=(hmsData.deviations||[]).length?hmsData.deviations.map(d=>`<div class="hms-deviation"><div><span class="status ${d.status==='closed'?'active':''}">${hmsStatus(d.status)}</span><strong>${escapeHtml(d.title)}</strong><small>${escapeHtml(d.employees?.employee_number||'')} · ${escapeHtml(d.employees?.full_name||'')} · ${hmsCategory(d.category)} · ${escapeHtml(d.severity)}</small><p>${escapeHtml(d.description)}</p></div><label>Status<select data-hms-status="${d.id}"><option value="new" ${d.status==='new'?'selected':''}>Ny</option><option value="in_progress" ${d.status==='in_progress'?'selected':''}>Under behandling</option><option value="closed" ${d.status==='closed'?'selected':''}>Lukket</option></select></label><label>Behandlingskommentar<textarea data-hms-comment="${d.id}" rows="2">${escapeHtml(d.admin_comment||'')}</textarea></label><button class="secondary" data-hms-save="${d.id}">Lagre behandling</button></div>`).join(''):'<p class="muted">Ingen HMS-avvik er meldt.</p>'}else{$('#employeeHmsDocuments').innerHTML=hmsDocumentRows(false);$('#employeeHmsDeviations').innerHTML=(hmsData.deviations||[]).length?hmsData.deviations.map(d=>`<div class="hms-row"><div><strong>${escapeHtml(d.title)}</strong><small>${hmsStatus(d.status)} · ${hmsCategory(d.category)} · ${new Date(d.created_at).toLocaleDateString('nb-NO')}</small>${d.admin_comment?`<p>${escapeHtml(d.admin_comment)}</p>`:''}</div></div>`).join(''):'<p class="muted">Du har ikke sendt noen avvik.</p>'}}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Filen kunne ikke leses.'));reader.readAsDataURL(file)})}
