function monthRange(){const month=localMonth(),[year,m]=month.split('-').map(Number);return{from:`${month}-01`,to:`${month}-${String(new Date(Date.UTC(year,m,0)).getUTCDate()).padStart(2,'0')}`}}
async function loadSickLeave(adminView=false){let path='/functions/v1/sick-leave';if(adminView){const from=$('#sickStatsFrom').value,to=$('#sickStatsTo').value;path+=`?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`}sickLeaveData=await authenticated(path);renderSickLeave()}
function sickRequestHtml(r,adminView=false){const employee=r.employees||{},period=r.start_date===r.end_date?displayDate(r.start_date):`${displayDate(r.start_date)}–${displayDate(r.end_date)}`;return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:sickTypeText(r.absence_type)}</strong><p>${adminView?sickTypeText(r.absence_type)+' · ':''}${period}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${sickStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?`<div class="sick-actions"><label>Kommentar<textarea data-sick-comment="${r.id}" rows="2" placeholder="Påkrevd ved avvisning"></textarea></label><button class="secondary" data-sick-handle="${r.id}" data-status="rejected">Avvis</button><button class="primary" data-sick-handle="${r.id}" data-status="approved">Godkjenn</button></div>`:''}</article>`}
function renderSickLeave(){if(currentEmployee?.role==='admin'){const stats=sickLeaveData.statistics||{};$('#sickStats').innerHTML=`<div><span>Sykefravær</span><strong>${Number(stats.absence_percentage||0).toLocaleString('nb-NO',{maximumFractionDigits:2})} %</strong></div><div><span>Godkjente timer</span><strong>${hours(stats.sick_hours)}</strong></div><div><span>Forventede timer</span><strong>${hours(stats.expected_hours)}</strong></div>`;const requests=sickLeaveData.requests||[];$('#adminSickRequests').innerHTML=requests.length?requests.map(r=>sickRequestHtml(r,true)).join(''):'<p class="muted">Ingen fraværsmeldinger i perioden.</p>'}else{const requests=sickLeaveData.requests||[];$('#employeeSickRequests').innerHTML=requests.length?requests.map(r=>sickRequestHtml(r)).join(''):'<p class="muted">Du har ikke sendt noen fraværsmeldinger.</p>'}}
function updateSickForm(){const medical=$('#sickType').value==='medical_certificate',today=localDate();$('#sickStart').max=today;$('#sickEnd').max=today;$('#sickEndLabel').classList.toggle('hidden',!medical);$('#sickEnd').required=medical;if(!medical)$('#sickEnd').value=$('#sickStart').value;$('#submitSickLeave').disabled=!$('#sickRoutineAck').checked}
$('#openSickLeave').onclick=async()=>{const today=localDate();$('#sickStart').value=today;$('#sickStart').max=today;$('#sickEnd').value=today;$('#sickEnd').max=today;$('#sickRoutineAck').checked=false;updateSickForm();try{await loadSickLeave();$('#sickLeaveDialog').showModal()}catch(error){show(error.message)}};
$('#closeSickLeave').onclick=()=>$('#sickLeaveDialog').close();
$('#sickType').onchange=updateSickForm;$('#sickStart').onchange=updateSickForm;$('#sickRoutineAck').onchange=updateSickForm;
$('#sickLeaveForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,type=$('#sickType').value,start=$('#sickStart').value,end=type==='medical_certificate'?$('#sickEnd').value:start;button.disabled=true;button.textContent='Sender …';try{const data=await authenticated('/functions/v1/sick-leave',{method:'POST',body:{action:'submit',absence_type:type,start_date:start,end_date:end,employee_note:$('#sickNote').value.trim(),routine_acknowledged:$('#sickRoutineAck').checked}});show(data.email_sent?'Sykefraværet er sendt til admin.':'Sykefraværet er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();await loadSickLeave();updateSickForm()}catch(error){show(error.message)}finally{button.textContent='Send sykefravær';updateSickForm()}};
const initialSickRange=monthRange();$('#sickStatsFrom').value=initialSickRange.from;$('#sickStatsTo').value=initialSickRange.to;
$('#loadSickStats').onclick=()=>loadSickLeave(true).catch(error=>show(error.message));
$('#adminSickRequests').onclick=async event=>{const button=event.target.closest('[data-sick-handle]');if(!button)return;const status=button.dataset.status,id=button.dataset.sickHandle,comment=document.querySelector(`[data-sick-comment="${id}"]`).value.trim();if(status==='rejected'&&comment.length<3)return show('Skriv en kort kommentar ved avvisning.');if(!confirm(status==='approved'?'Godkjenne fraværet og føre 8 timer per aktuell hverdag?':'Avvise fraværsmeldingen?'))return;button.disabled=true;try{await authenticated('/functions/v1/sick-leave',{method:'PATCH',body:{action:'handle',id,status,admin_comment:comment}});show(status==='approved'?'Fraværet er godkjent og ført i timelisten.':'Fraværet er avvist.');await loadSickLeave(true)}catch(error){show(error.message)}finally{button.disabled=false}};

const vacationTypeText=value=>({vacation:'Ferie',leave:'Permisjon'})[value]||value;
const vacationStatusText=value=>({pending:'Til behandling',approved:'Godkjent',rejected:'Avvist'})[value]||value;
const currentYear=()=>Number(localDate().slice(0,4));
function addLocalDays(value,days){const date=new Date(`${value}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)}
async function loadVacation(adminView=false){const year=adminView?Number($('#vacationAdminYear').value):currentYear();vacationData=await authenticated(`/functions/v1/vacation?year=${year}`);renderVacation(adminView)}
function vacationRequestHtml(r,adminView=false){const employee=r.employees||{},period=`${displayDate(r.start_date)}–${displayDate(r.end_date)}`;return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:vacationTypeText(r.request_type)}</strong><p>${adminView?vacationTypeText(r.request_type)+' · ':''}${period} · ${r.requested_days} ${r.requested_days===1?'dag':'dager'}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${vacationStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?vacationActions(r.id,'handle'):''}</article>`}
function carryoverHtml(r,adminView=false){const employee=r.employees||{};return `<article class="sick-request"><div class="sick-request-head"><div><strong>${adminView?`${escapeHtml(employee.employee_number||'')} · ${escapeHtml(employee.full_name||'')}`:'Overføring'}</strong><p>${r.days} ${r.days===1?'dag':'dager'} · ${r.from_year} → ${r.to_year}</p>${r.employee_note?`<p class="muted">${escapeHtml(r.employee_note)}</p>`:''}${r.admin_comment?`<p class="muted">Kommentar: ${escapeHtml(r.admin_comment)}</p>`:''}</div><span class="status ${r.status}">${vacationStatusText(r.status)}</span></div>${adminView&&r.status==='pending'?vacationActions(r.id,'handle_carryover'):''}</article>`}
function vacationActions(id,action){return `<div class="sick-actions"><label>Kommentar<textarea data-vacation-comment="${id}" rows="2" placeholder="Påkrevd ved avvisning"></textarea></label><button class="secondary" data-vacation-handle="${id}" data-action="${action}" data-status="rejected">Avvis</button><button class="primary" data-vacation-handle="${id}" data-action="${action}" data-status="approved">Godkjenn</button></div>`}
function renderVacation(adminView=false){if(adminView){const balances=vacationData.balances||[];$('#vacationBalances').innerHTML=balances.length?`<table><thead><tr><th>Ansatt</th><th>Tilgjengelig</th><th>Godkjent ferie</th><th>Til behandling</th><th>Overført ut</th><th>Gjenstår</th></tr></thead><tbody>${balances.map(b=>`<tr><td><strong>${escapeHtml(b.employee_number)} · ${escapeHtml(b.full_name)}</strong></td><td>${b.available}</td><td>${b.used}</td><td>${b.pending}</td><td>${b.transferred}</td><td><strong>${b.remaining}</strong></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Ingen ansatte funnet.</div>';$('#adminVacationRequests').innerHTML=(vacationData.requests||[]).length?vacationData.requests.map(r=>vacationRequestHtml(r,true)).join(''):'<p class="muted">Ingen søknader dette året.</p>';$('#adminCarryoverRequests').innerHTML=(vacationData.carryovers||[]).length?vacationData.carryovers.map(r=>carryoverHtml(r,true)).join(''):'<p class="muted">Ingen overføringssøknader dette året.</p>';return}const b=vacationData.balance||{};$('#vacationBalance').innerHTML=`<div><span>Tilgjengelig ${b.year||currentYear()}</span><strong>${b.available||25} dager</strong></div><div><span>Godkjent ferie</span><strong>${b.used||0} dager</strong></div><div><span>Gjenstår</span><strong>${b.remaining??25} dager</strong></div>`;$('#employeeVacationRequests').innerHTML=(vacationData.requests||[]).length?vacationData.requests.map(r=>vacationRequestHtml(r)).join(''):'<p class="muted">Du har ingen ferie- eller permisjonssøknader.</p>';$('#employeeCarryovers').innerHTML=(vacationData.carryovers||[]).length?vacationData.carryovers.map(r=>carryoverHtml(r)).join(''):'<p class="muted">Ingen overføringssøknader.</p>'}
function setVacationDates(){const earliest=addLocalDays(localDate(),14);$('#vacationStart').min=earliest;$('#vacationEnd').min=$('#vacationStart').value||earliest;if(!$('#vacationStart').value)$('#vacationStart').value=earliest;if(!$('#vacationEnd').value||$('#vacationEnd').value<$('#vacationStart').value)$('#vacationEnd').value=$('#vacationStart').value}
$('#openVacation').onclick=async()=>{setVacationDates();$('#carryoverYear').value=currentYear();try{await loadVacation();$('#vacationDialog').showModal()}catch(error){show(error.message)}};
$('#closeVacation').onclick=()=>$('#vacationDialog').close();$('#vacationStart').onchange=setVacationDates;
$('#vacationForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Sender …';try{const data=await authenticated('/functions/v1/vacation',{method:'POST',body:{action:'submit',request_type:$('#vacationType').value,start_date:$('#vacationStart').value,end_date:$('#vacationEnd').value,employee_note:$('#vacationNote').value.trim()}});show(data.email_sent?'Ønsket er sendt til admin.':'Ønsket er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();setVacationDates();await loadVacation()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Send ønske'}};
$('#carryoverForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const data=await authenticated('/functions/v1/vacation',{method:'POST',body:{action:'carryover',from_year:Number($('#carryoverYear').value),days:Number($('#carryoverDays').value),employee_note:$('#carryoverNote').value.trim()}});show(data.email_sent?'Overføringssøknaden er sendt til admin.':'Søknaden er registrert, men e-postvarselet kunne ikke sendes.');event.target.reset();$('#carryoverYear').value=currentYear();await loadVacation()}catch(error){show(error.message)}finally{button.disabled=false}};
$('#vacationAdminYear').value=currentYear();$('#loadVacationAdmin').onclick=()=>loadVacation(true).catch(error=>show(error.message));
async function handleVacationClick(event){const button=event.target.closest('[data-vacation-handle]');if(!button)return;const id=button.dataset.vacationHandle,status=button.dataset.status,action=button.dataset.action,comment=document.querySelector(`[data-vacation-comment="${id}"]`).value.trim();if(status==='rejected'&&comment.length<3)return show('Skriv en kort kommentar ved avvisning.');if(!confirm(status==='approved'?'Godkjenne søknaden?':'Avvise søknaden?'))return;button.disabled=true;try{const data=await authenticated('/functions/v1/vacation',{method:'PATCH',body:{action,id,status,admin_comment:comment}});show(data.email_sent?(status==='approved'?'Søknaden er godkjent og den ansatte er varslet.':'Søknaden er avvist og den ansatte er varslet.'):'Søknaden er behandlet, men e-posten kunne ikke sendes.');await loadVacation(true)}catch(error){show(error.message)}finally{button.disabled=false}}
$('#adminVacationRequests').onclick=handleVacationClick;$('#adminCarryoverRequests').onclick=handleVacationClick;

const hrStatusText=value=>({draft:'Utkast',locked:'Låst – klar for signering',pending_signature:'Til signering',signed:'Signert',cancelled:'Avbrutt',not_required:'Ingen signering',pending:'Venter på signering',declined:'Avvist'})[value]||value;
async function loadHr(){hrData=await authenticated('/functions/v1/hr');renderHr()}
function hrDocumentRows(adminView=false){const docs=hrData.documents||[];return docs.length?docs.map(d=>`<div class="hms-row"><div><strong>${escapeHtml(d.title)}</strong><small>${adminView?`${escapeHtml(d.employees?.employee_number||'')} · ${escapeHtml(d.employees?.full_name||'')} · `:''}${new Date(d.created_at).toLocaleDateString('nb-NO')} · ${hrStatusText(d.signature_status)}${d.read_at?' · Lest':''}</small></div><div class="actions"><a class="small hms-link" href="${d.url}" target="_blank" rel="noopener" data-hr-open="${d.id}">Åpne PDF</a></div></div>`).join(''):'<p class="muted">Ingen dokumenter er lagt inn.</p>'}
function hrContractRows(adminView=false){const contracts=hrData.contracts||[];return contracts.length?contracts.map(c=>`<article class="sick-request"><div class="sick-request-head"><div><strong>${escapeHtml(c.title)}</strong><p>${adminView?`${escapeHtml(c.employees?.employee_number||'')} · ${escapeHtml(c.employees?.full_name||'')} · `:''}Versjon ${c.version}</p></div><span class="status ${c.status}">${hrStatusText(c.status)}</span></div><details><summary>Vis kontrakt</summary><pre class="contract-preview">${escapeHtml(c.locked_content||c.content)}</pre></details>${adminView&&c.status==='draft'?`<div class="actions"><button class="secondary" data-contract-edit="${c.id}">Rediger</button><button class="primary" data-contract-lock="${c.id}">Lås kontrakt</button></div>`:''}</article>`).join(''):'<p class="muted">Ingen kontrakter er opprettet.</p>'}
function renderHr(){if(currentEmployee?.role==='admin'){const options='<option value="">Velg ansatt</option>'+hrData.employees.map(e=>`<option value="${e.id}">${escapeHtml(e.employee_number)} · ${escapeHtml(e.full_name)}</option>`).join('');$('#hrDocumentEmployee').innerHTML='<option value="all">Alle ansatte</option>'+options.slice(options.indexOf('</option>')+9);$('#hrContractEmployee').innerHTML=options;$('#adminHrDocuments').innerHTML=hrDocumentRows(true);$('#adminHrContracts').innerHTML=hrContractRows(true)}else{$('#employeeHrDocuments').innerHTML=hrDocumentRows(false);$('#employeeHrContracts').innerHTML=hrContractRows(false)}}
$('#openEmployeeHr').onclick=async()=>{try{await loadHr();$('#employeeHrDialog').showModal()}catch(error){show(error.message)}};
$('#closeEmployeeHr').onclick=()=>$('#employeeHrDialog').close();
$('#employeeHrDocuments').onclick=async event=>{const link=event.target.closest('[data-hr-open]');if(link)authenticated('/functions/v1/hr',{method:'PATCH',body:{action:'mark_read',id:link.dataset.hrOpen}}).catch(()=>{})};
$('#hrUploadForm').onsubmit=async event=>{event.preventDefault();const file=$('#hrDocumentFile').files[0],button=event.submitter;if(!file)return;button.disabled=true;button.textContent='Laster opp …';try{const data=await authenticated('/functions/v1/hr',{method:'POST',body:{action:'upload_document',title:$('#hrDocumentTitle').value.trim(),employee_id:$('#hrDocumentEmployee').value,file_name:file.name,mime_type:file.type||'application/pdf',content_base64:await fileBase64(file),requires_signature:$('#hrRequiresSignature').checked}});event.target.reset();show(`Dokumentet er lagt i arkivet til ${data.recipient_count} mottaker(e).`);await loadHr()}catch(error){show(error.message)}finally{button.disabled=false;button.textContent='Last opp og varsle'}};
function resetContractForm(){$('#hrContractForm').reset();$('#hrContractId').value='';$('#hrContractTitle').value='Arbeidsavtale';$('#hrContractEmployee').disabled=false;$('#cancelContractEdit').classList.add('hidden')}
$('#hrContractForm').onsubmit=async event=>{event.preventDefault();const id=$('#hrContractId').value,button=event.submitter;button.disabled=true;try{await authenticated('/functions/v1/hr',{method:id?'PATCH':'POST',body:{action:id?'update_contract':'create_contract',...(id?{id}:{}),employee_id:$('#hrContractEmployee').value,title:$('#hrContractTitle').value.trim(),content:$('#hrContractContent').value.trim()}});show(id?'Kontraktsutkastet er oppdatert.':'Kontraktsutkastet er opprettet.');resetContractForm();await loadHr()}catch(error){show(error.message)}finally{button.disabled=false}};
$('#cancelContractEdit').onclick=resetContractForm;
$('#adminHrContracts').onclick=async event=>{const edit=event.target.closest('[data-contract-edit]'),lock=event.target.closest('[data-contract-lock]');if(edit){const c=hrData.contracts.find(x=>x.id===edit.dataset.contractEdit);$('#hrContractId').value=c.id;$('#hrContractEmployee').value=c.employee_id;$('#hrContractEmployee').disabled=true;$('#hrContractTitle').value=c.title;$('#hrContractContent').value=c.content;$('#cancelContractEdit').classList.remove('hidden');$('#hrContractContent').focus()}if(lock){if(!confirm('Låse kontrakten? Innholdet kan ikke redigeres etterpå.'))return;lock.disabled=true;try{const data=await authenticated('/functions/v1/hr',{method:'PATCH',body:{action:'lock_contract',id:lock.dataset.contractLock}});show(data.email_sent?'Kontrakten er låst og den ansatte er varslet.':'Kontrakten er låst, men e-postvarselet kunne ikke sendes.');await loadHr()}catch(error){show(error.message)}finally{lock.disabled=false}}};

if(session?.access_token)openApp();
setInterval(()=>{if(currentEmployee?.role==='admin')loadEmployees().catch(()=>{})},60000);
